{"id":"7d031f83-b80a-44b9-a898-57cfd97d5120","inserted_at":"2026-05-07T15:36:11.790987+00:00","updated_at":"2026-05-07T15:36:11.790987+00:00","type":"sql","name":"Reimposta Mete Consigliate e aggiorna get_pois RPC","description":"","content":{"sql":"-- =========================================================================\r\n-- MIGRATION V11: FIX \"METE CONSIGLIATE\" E ALLINEAMENTO RPC\r\n-- 1. Reimposta il flag is_recommended su alcune mete chiave.\r\n-- 2. Aggiorna l'RPC get_pois() per restituire TUTTI i campi necessari alla Home.\r\n-- =========================================================================\r\n\r\n-- 1. Rimettiamo \"Mete Consigliate\" su 3 POI strategici per far riapparire la sezione in Home\r\nUPDATE public.pois \r\nSET is_recommended = true\r\nWHERE name IN ('Castello Aragonese', 'Oasi Palude La Vela', 'MuDi - Museo Diocesano');\r\n\r\n-- 2. Aggiorniamo get_pois() affinché restituisca TUTTI i campi, inclusi quelli di Governance\r\nDROP FUNCTION IF EXISTS get_pois();\r\n\r\nCREATE FUNCTION get_pois()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    crowd_level INTEGER,\r\n    has_water BOOLEAN,\r\n    is_accessible BOOLEAN,\r\n    alternative_poi_id UUID,\r\n    is_recommended BOOLEAN,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8,\r\n    p_iva TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        p.crowd_level,\r\n        p.has_water,\r\n        p.is_accessible,\r\n        p.alternative_poi_id,\r\n        p.is_recommended,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude,\r\n        p.p_iva\r\n    FROM public.pois p\r\n    WHERE p.is_active = true\r\n    ORDER BY p.name ASC;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n","content_id":"7d031f83-b80a-44b9-a898-57cfd97d5120","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
